assert len(_RAW) % 3 == 0, len(_RAW)
PLANTS: list[dict] = []
for i, row in enumerate(_RAW):
    family, title, core, boot, test, line, nit, defect, reach, missing, fix, needles, notfam = row
    PLANTS.append(
        _p(
            family,
            family,
            f"reef{1000 + i}",
            title,
            core,
            boot,
            test,
            line,
            nit,
            defect,
            reach,
            missing,
            fix,
            needles,
            notfam,
        )
    )

assert len({p["slug"] for p in PLANTS}) == len(PLANTS)
assert len({p["family"] for p in PLANTS}) == len(PLANTS)
_old = {_BASE.PLANTS[i]["family"] for i in range(len(_BASE.PLANTS))}
_old |= {_BASE.PLANTS[i]["slug"] for i in range(len(_BASE.PLANTS))}
_clash = [p["family"] for p in PLANTS if p["family"] in _old] + [
    p["slug"] for p in PLANTS if p["slug"] in _old
]
assert not _clash, _clash

FACTORY_DIR = Path(__file__).resolve().parents[1] / (
    "outputs/raw/2026-08-19-agentic/code-review-preference-factory"
)

_SKIP_SUBSTR = (
    "buildx-builder-driver-opt-leftover",
    "buildx-provenance-mode-leftover",
    "temporal-heartbeat",
    "cadence-replay",
    "airflow-catchup",
    "ray-pg-actor-lease-dup",
    "kubeflow-recurring-catchup",
    "mlserver-stream-replay",
    "lazylibrarian-book-id-reuse",
    "romm-rom-id-reuse",
    "dashy-section-name-case",
    "id-reuse",
    "uid-reuse",
    "uuid-reuse",
    "oauth",
    "oidc",
    "saml",
    "webgpu",
    "webnn",
)


def _used_from_disk() -> set[str]:
    used: set[str] = set()
    if not FACTORY_DIR.is_dir():
        return used
    fam_re = re.compile(r"family=`([^`]+)`")
    id_re = re.compile(r"`crp-r\d+-([^`]+)`")
    for path in FACTORY_DIR.glob("NOTES-r*.md"):
        text = path.read_text()
        used.update(fam_re.findall(text))
        used.update(id_re.findall(text))
    for path in FACTORY_DIR.glob("batch-r*.jsonl"):
        for line in path.read_text().splitlines():
            if not line.strip():
                continue
            rec = json.loads(line)
            rid = rec.get("id") or ""
            m = re.match(r"crp-r\d+-(.+)$", rid)
            if m:
                used.add(m.group(1))
            fam = (rec.get("meta") or {}).get("family")
            if fam:
                used.add(fam)
    return used


def _skip(plant: dict, used: set[str]) -> bool:
    fam = plant["family"]
    slug = plant["slug"]
    if fam in used or slug in used:
        return True
    blob = f"{fam} {slug}".lower()
    return any(s in blob for s in _SKIP_SUBSTR)


def unused_plants() -> list[dict]:
    used = _used_from_disk()
    return [p for p in PLANTS if not _skip(p, used)]


def plants_for_round(round_n: int) -> list[dict]:
    if round_n < 1:
        raise SystemExit(f"bad round {round_n}")
    unused = unused_plants()
    if len(unused) < 3:
        raise SystemExit(f"no unused plant triple for r{round_n} (left={len(unused)})")
    return unused[:3]


def notes_for(round_n: int, recs: list[dict]) -> str:
    fams = [r["meta"]["family"] for r in recs]
    ids = [r["id"] for r in recs]
    lines = [
        f"# code-review-preference-factory — NOTES r{round_n}",
        "",
        "Novel coverage: 99.5%",
        "",
        f"Headline: blocking defect vs nit/LGTM on {', '.join(fams)} (low-code/BI/CRM/calendar/notes stretch)",
        "",
        "Construction: divergence-point DPO (shared 7-step prefix; first differing tool_call is the review verdict). Same top-level goal both sides. Chosen posts issue (blocking) REQUEST_CHANGES. Rejected posts nits and APPROVE. Discarded drafts that changed the PR. Fuel: ARCTIC, BitsAI-CR, Graphite blocking-vs-nits. Stretch is a NEW platform family (NocoBase/Appsmith/Retool/ToolJet/Budibase, Firebase, Metabase/Superset/Redash/Lightdash/Evidence, Chatwoot/Zammad/osTicket, Cal.com, AFFiNE/AppFlowy/Anytype, Twenty/Espo/Suite/Vtiger, Formbricks/HeyForm) SeaTable/Teable/Grist/APITable/Rowy, Marimo/Quarto/Observable/Hex/Deepnote, Hightouch/Census/Grouparoo/RudderStack, Delta/Hudi/Iceberg/Dremio, Kong/Tyk/APISIX/KrakenD, Penpot/Excalidraw, Postal/mailcow/Mailu, Weblate/Tolgee/Pontoon, DocuSeal/Documenso/Paperless, Moodle/Open edX/Chamilo, Owncast/MediaMTX, Plane/Vikunja, InvenTree, GLPI/FreeScout, Netdata/Zabbix/Icinga. Graylog/Fluent Bit/Logstash/Filebeat/Vector, Infisical/SOPS/Doppler/Chamber, Borg/restic REST/rustic, OpenRemote/FUXA/Node-RED/ESPHome/Zigbee2MQTT, Keystone/Sanity/Wagtail, Holistics/GoodData/ThoughtSpot, LimeSurvey/KoBo/ODK, Pulp/devpi/Aptly, Caddy/Traefik, Zulip/Jitsi/BBB, Firefly/Actual/Akaunting/Kimai, OrangeHRM/Leantime/OpenProject/Redmine, pretix/PostHog. plus unused application bugs (TOCTOU, ORM RMW, XSS, timezone fold, unique constraint) — not id-reuse clones, not query-string HTML clones, not language open-swap cartesian.",
        "",
        "New families this stretch (not r161-r252 OAuth/OIDC/SAML; not r253-r276 privacy-sandbox; not r277-r312 WebGPU/WebNN/IWA; not r313-r431 CSS/HTML query-string checkout clones; not r537 temporal-heartbeat-timeout-double / cadence-replay-nondet-now / airflow-catchup-true-charge; not r728 buildx leftovers; not r816 ray-pg-actor-lease-dup / kubeflow-recurring-catchup / mlserver-stream-replay; not r994 lazylibrarian-book-id-reuse / romm-rom-id-reuse / dashy-section-name-case; not prior *id-reuse clones): NocoBase/Appsmith/Retool/ToolJet/Budibase, Firebase Firestore/RTDB/Functions/Storage, Metabase/Superset/Redash/Lightdash/Evidence/Cube/Soda/Elementary, Chatwoot/Zammad/osTicket/UVdesk/Freshdesk, Cal.com/EasyAppointments/CalDAV, AFFiNE/AppFlowy/Anytype/Dendron/Zim/CherryTree/Obsidian/Foam, Twenty/EspoCRM/SuiteCRM/Vtiger, Formbricks/HeyForm/Open Collective, Jupyter/Papermill/Ploomber/Zeppelin.",
        "",
        "Records:",
    ]
    for rec, plant in zip(recs, plants_for_round(round_n)):
        lines.append(
            f"- `{rec['id']}` sin=`missed defect / nitpicks` class=`{plant['family']}-blocking` family=`{plant['family']}` fork=step 8"
        )
    lines.extend(
        [
            "",
            f"IDs: {ids}",
            "",
            "Weakest critique: still names the same-goal quality delta and the discarded changed-problem draft. Distinct from r161-r252 OAuth/OIDC/SAML, r253-r276 privacy-sandbox, r277-r312 WebGPU/IWA, r313-r431 HTML/CSS query-string clones, r537 temporal/cadence/airflow, r713-r722 open-swap, r816 ray/kubeflow/mlserver, r994 lazylibrarian/romm/dashy, and prior id-reuse clones.",
            "",
            "No Thalamic six-field core. No spikes. Observations are designed plants.",
            "",
            "Next gaps: more low-code unique indexes, more BI cache keys, more CRM sequence allocation.",
            "",
        ]
    )
    return "\n".join(lines)


def write_round(round_n: int, staging: Path) -> list[str]:
    recs = [pair(p, round_n, i) for i, p in enumerate(plants_for_round(round_n))]
    batch = staging / f"batch-r{round_n:02d}.jsonl"
    notes = staging / f"NOTES-r{round_n:02d}.md"
    with batch.open("w") as handle:
        for rec in recs:
            handle.write(json.dumps(rec, ensure_ascii=False) + "\n")
    notes.write_text(notes_for(round_n, recs))
    return [r["id"] for r in recs]


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--round", type=int, required=True)
    parser.add_argument("--staging", type=Path, required=True)
    args = parser.parse_args()
    ids = write_round(args.round, args.staging)
    print(json.dumps({"round": args.round, "ids": ids, "staging": str(args.staging)}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
